import math
from collections import defaultdict

class Solution:
    def numberOfSubsequences(self, nums: list[int]) -> int:
        n = len(nums)
        ans = 0
        left_ratios = defaultdict(int)

        for r in range(4, n - 2):
            q = r - 2
            for p in range(0, q - 1):
                g = math.gcd(nums[p], nums[q])
                left_ratios[(nums[p] // g, nums[q] // g)] += 1

            for s in range(r + 2, n):
                g = math.gcd(nums[s], nums[r])
                ans += left_ratios[(nums[s] // g, nums[r] // g)]

        return ans

class Solution {
public:
    long long numberOfSubsequences(vector<int>& nums) {
        int n = nums.size();
        long long ans = 0;
        map<pair<int, int>, int> leftRatios;

        for (int r = 4; r < n - 2; ++r) {
            int q = r - 2;
            for (int p = 0; p < q - 1; ++p) {
                int g = std::gcd(nums[p], nums[q]);
                leftRatios[{nums[p] / g, nums[q] / g}]++;
            }
            for (int s = r + 2; s < n; ++s) {
                int g = std::gcd(nums[s], nums[r]);
                auto it = leftRatios.find({nums[s] / g, nums[r] / g});
                if (it != leftRatios.end()) {
                    ans += it->second;
                }
            }
        }
        return ans;
    }
};

class Solution {
    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    public long numberOfSubsequences(int[] nums) {
        int n = nums.length;
        long ans = 0;
        Map<Long, Integer> leftRatios = new HashMap<>();

        for (int r = 4; r < n - 2; ++r) {
            int q = r - 2;
            for (int p = 0; p < q - 1; ++p) {
                int g = gcd(nums[p], nums[q]);
                long key = (((long)(nums[p] / g)) << 32) | (long)(nums[q] / g);
                leftRatios.put(key, leftRatios.getOrDefault(key, 0) + 1);
            }
            for (int s = r + 2; s < n; ++s) {
                int g = gcd(nums[s], nums[r]);
                long key = (((long)(nums[s] / g)) << 32) | (long)(nums[r] / g);
                ans += leftRatios.getOrDefault(key, 0);
            }
        }
        return ans;
    }
}

